--- onekeyirc-0.1.26/tests/test_credential_descendants.c
+++ onekeyirc-0.1.27/tests/test_credential_descendants.c
@@ -0,0 +1,242 @@
+/* Production helper lifecycle with real private fork/exec/pipes/signals.
+ * This executable supplies an adversarial helper, not GnuPG or a keyring.
+ * On Linux, test-only subreaping also collects every created descendant. */
+#ifndef _GNU_SOURCE
+#define _GNU_SOURCE
+#endif
+#include <assert.h>
+#include <errno.h>
+#include <poll.h>
+#include <signal.h>
+#include <stdio.h>
