+++ vipirc-0.7.28/tests/test_credential_signals.c
@@ -0,0 +1,71 @@
+/* Child-ownership admission, with real helpers and private files. A wrapper
+ * counts production fork calls; the helper remains the existing executable
+ * fixture rather than GnuPG or a user's keyring. */
+#ifndef _GNU_SOURCE
+#define _GNU_SOURCE
+#endif
+#include <sys/types.h>
+#include <unistd.h>
+static pid_t counted_fork(void);
+#define fork counted_fork
+#include "credentials.c"
+#undef fork
+#define main existing_credential_suite
+#include "test_credentials.c"
+#undef main
+
+static unsigned forks_started;
+static pid_t counted_fork(void) { ++forks_started; return fork(); }
+static void nonreaping_handler(int signal_number) { (void)signal_number; }
+
+int main(int argc, char **argv)
+{
+    if (!strcmp(argv[0], "gpg")) return fake_gpg(argc, argv);
+    char directory[] = "/tmp/irc-credential-signals-XXXXXX";
+    char executable[CONFIG_PATH_MAX], program[CONFIG_PATH_MAX], source[CONFIG_PATH_MAX];
+    char destination[CONFIG_PATH_MAX], error[512];
+    assert(realpath(argv[0], executable) && mkdtemp(directory));
+    assert(snprintf(program, sizeof program, "%s/gpg", directory) > 0);
+    assert(snprintf(source, sizeof source, "%s/input.gpg", directory) > 0);
+    assert(snprintf(destination, sizeof destination, "%s/output.gpg", directory) > 0);
+    assert(!symlink(executable, program) && !setenv("PATH", directory, 1));
+    file_write(source, "hang", 4, 0600);
+    struct sigaction original, action;
+    assert(!sigaction(SIGCHLD, NULL, &original));
+    struct Policy { const char *name; void (*handler)(int); int flags, allowed; } policies[] = {
+        {"SIG_IGN", SIG_IGN, 0, 0},
+#ifdef SA_NOCLDWAIT
+        {"SIG_DFL+SA_NOCLDWAIT", SIG_DFL, SA_NOCLDWAIT, 0},
+        {"handler+SA_NOCLDWAIT", nonreaping_handler, SA_NOCLDWAIT, 0},
+#endif
+        {"SIG_DFL", SIG_DFL, 0, 1},
+        {"non-reaping handler", nonreaping_handler, SA_NOCLDSTOP, 1}
+    };
+    int okay = 1;
+    for (size_t i = 0; i < sizeof policies / sizeof policies[0]; ++i) {
+        memset(&action, 0, sizeof action); sigemptyset(&action.sa_mask);
+        action.sa_handler = policies[i].handler; action.sa_flags = policies[i].flags;
+        assert(!sigaction(SIGCHLD, &action, NULL));
+        for (int encrypt = 0; encrypt < 2; ++encrypt) {
+            unsigned before_forks = forks_started;
+            int before_fds = descriptors();
+            error[0] = 0;
+            Credential *r = encrypt ? NULL : credential_start(source, milliseconds(), error, sizeof error);
+            CredentialCreate *w = encrypt ? credential_create_start(destination, fingerprint, "hang", milliseconds(), error, sizeof error) : NULL;
+            int started = r || w;
+            if (r) credential_cancel(r);
+            if (w) credential_create_cancel(w);
+            reap_all();
+            unsigned made = forks_started - before_forks;
+            if (started != policies[i].allowed || made != (unsigned)policies[i].allowed) okay = 0;
+            if (!started) assert(strstr(error, "SIGCHLD"));
+            assert(descriptors() == before_fds && access(destination, F_OK) < 0);
+            printf("%s %s: started=%d forks=%u expected=%d; descriptors restored; destination absent\n",
+                   encrypt ? "encrypt" : "decrypt", policies[i].name, started, made, policies[i].allowed);
+        }
+    }
+    assert(!sigaction(SIGCHLD, &original, NULL));
+    assert(!unlink(source) && !unlink(program) && !rmdir(directory));
+    if (!okay) fputs("FAIL: automatic child reaping was admitted before helper launch\n", stderr);
+    return okay ? 0 : 1;
+}

vipirc-0.7.28.tests/test_net_resolver_ownership.c:
--- vipirc-0.7.27/tests/test_net_resolver_ownership.c
+++ vipirc-0.7.28/tests/test_net_resolver_ownership.c
@@ -0,0 +1,123 @@
+/* Resolver child ownership with real fork/exit/wait and signal dispositions.
+ * No DNS request is made. The overridden resolver returns locally or waits
+ * for the production cancellation signal. Auto-reaping baseline probes allow
+ * their own helper to exit, then observe an attempted signal to its stale PID;
+ * no unrelated process is targeted and PID reuse is not forced. */
+#define _POSIX_C_SOURCE 200809L
+#include "net.h"
+#include <errno.h>
+#include <netdb.h>
+#include <poll.h>
+#include <signal.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <sys/types.h>
+#include <sys/wait.h>
+#include <time.h>
+#include <unistd.h>
+
+static unsigned fork_calls, pipe_calls, stale_signal_calls;
+static pid_t helper_pid;
+static int blocked_lookup;
+static volatile sig_atomic_t notifications;
+
+pid_t resolver_ownership_fork(void)
+{
+    ++fork_calls;
+    pid_t pid = fork();
+    if (pid > 0) helper_pid = pid;
+    return pid;
+}
+int resolver_ownership_pipe(int fds[2])
+{
+    ++pipe_calls;
+    return pipe(fds);
+}
+int resolver_ownership_kill(pid_t pid, int signal_number)
+{
+    if (pid == helper_pid && signal_number == SIGKILL && kill(pid, 0) < 0 && errno == ESRCH)
+        ++stale_signal_calls;
+    return kill(pid, signal_number);
+}
+int resolver_ownership_getaddrinfo(const char *name, const char *service,
+                                  const struct addrinfo *hints, struct addrinfo **out)
+{
+    (void)name; (void)service; (void)hints; (void)out;
+    while (blocked_lookup) pause();
+    return EAI_NONAME;
+}
+static void notification(int signo) { (void)signo; ++notifications; }
+static void require(int condition, const char *label)
+{
+    if (!condition) { fprintf(stderr, "%s (errno=%d)\n", label, errno); exit(2); }
+}
+static void restore(const struct sigaction *saved)
+{
+    struct sigaction actual;
+    require(sigaction(SIGCHLD, saved, NULL) == 0, "restore SIGCHLD disposition");
+    require(sigaction(SIGCHLD, NULL, &actual) == 0, "inspect restored SIGCHLD");
+    require(actual.sa_handler == saved->sa_handler, "restored SIGCHLD handler");
+#ifdef SA_NOCLDWAIT
+    require((actual.sa_flags & SA_NOCLDWAIT) == (saved->sa_flags & SA_NOCLDWAIT), "restored SIGCHLD auto-reaping flag");
+#endif
+    for (int signal_number = 1; signal_number <= SIGTERM; ++signal_number)
+        require(sigismember(&actual.sa_mask, signal_number) == sigismember(&saved->sa_mask, signal_number),
+                "restored handler mask");
+}
+static int check(const char *name, void (*handler)(int), int flags, int rejected)
+{
+    struct sigaction previous, desired;
+    char error[512] = "";
+    require(sigaction(SIGCHLD, NULL, &previous) == 0, "save SIGCHLD");
+    memset(&desired, 0, sizeof desired);
+    desired.sa_handler = handler; desired.sa_flags = flags;
+    require(sigemptyset(&desired.sa_mask) == 0, "empty handler mask");
+    require(sigaction(SIGCHLD, &desired, NULL) == 0, "install test SIGCHLD");
+    fork_calls = pipe_calls = stale_signal_calls = 0; helper_pid = 0;
+    blocked_lookup = !rejected;
+    Net *net = net_open("resolver-ownership.invalid", 6667, 0, NULL, error, sizeof error);
+    int correct;
+    if (rejected) {
+        correct = !net && !fork_calls && !pipe_calls && strstr(error, "SIGCHLD") != NULL;
+        if (net) {
+            /* Wait only for our auto-reaped helper. No waitable zombie is
+             * available to pin its identity in these baseline cases. */
+            int gone = 0;
+            int64_t deadline = net_now_ms() + 2000;
+            while (net_now_ms() < deadline) {
+                if (kill(helper_pid, 0) < 0 && errno == ESRCH) { gone = 1; break; }
+                struct timespec pause_time = {0, 1000000};
+                (void)nanosleep(&pause_time, NULL);
+            }
+            require(gone, "auto-reaped fixture child exited");
+            net_close(net);
+        }
+    } else {
+        correct = net && fork_calls == 1 && pipe_calls == 1;
+        require(net != NULL, "waitable resolver starts");
+        require(!net_detach_ready(net), "live waitable resolver prevents detach");
+        net_close(net);
+        errno = 0;
+        require(waitpid(helper_pid, NULL, WNOHANG) < 0 && errno == ECHILD, "cancelled resolver was collected");
+        require(kill(helper_pid, 0) < 0 && errno == ESRCH, "cancelled resolver no longer exists");
+    }
+    restore(&previous);
+    printf("{\"case\":\"%s\",\"rejected_before_fork\":%s,\"fork_calls\":%u,\"pipe_calls\":%u,\"stale_pid_signal_calls\":%u,\"policy_restored\":true,\"passed\":%s}\n",
+           name, rejected && !net ? "true" : "false", fork_calls, pipe_calls,
+           stale_signal_calls, correct ? "true" : "false");
+    return correct;
+}
+int main(void)
+{
+    int okay = 1;
+    signal(SIGPIPE, SIG_IGN); alarm(10);
+    if (!check("SIGCHLD ignored", SIG_IGN, 0, 1)) okay = 0;
+#ifdef SA_NOCLDWAIT
+    if (!check("SA_NOCLDWAIT", SIG_DFL, SA_NOCLDWAIT, 1)) okay = 0;
+    if (!check("handler plus SA_NOCLDWAIT", notification, SA_NOCLDWAIT, 1)) okay = 0;
+#endif
+    if (!check("default waitable children", SIG_DFL, 0, 0)) okay = 0;
+    if (!check("non-reaping handler", notification, 0, 0)) okay = 0;
+    return okay ? 0 : 1;
+}

vipirc-0.7.28.tests/test_net_tls_budget.c:
--- vipirc-0.7.27/tests/test_net_tls_budget.c
+++ vipirc-0.7.28/tests/test_net_tls_budget.c
@@ -0,0 +1,428 @@
+/* Real, verified loopback TLS with controlled records and socket backpressure.
+ * net.c is compiled with SSL_new/read/write/get_error renamed to the small
+ * observation wrappers below. Only the explicit want-read case injects an
+ * outcome; all other TLS operations and retry errors are from the library. */
+#define _POSIX_C_SOURCE 200809L
+#include "net.h"
+#include <arpa/inet.h>
+#include <errno.h>
+#include <poll.h>
+#include <signal.h>
+#include <stdint.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <sys/socket.h>
+#include <sys/wait.h>
+#include <time.h>
+#include <unistd.h>
+#include <openssl/err.h>
+#include <openssl/ssl.h>
+
+static const char ping[] = "PING :control-budget\r\n";
+static const char pong[] = "PONG :control-budget\r\n";
+static const char *scenario = "TLS fixture";
+static unsigned updates, ssl_read_calls;
+static int inject_write_error, injected_error;
+static SSL *observed_ssl;
+static pid_t server_pid;
+
+static void fail(const char *label)
+{
+    fprintf(stderr, "%s: %s (errno=%d)\n", scenario, label, errno);
+    ERR_print_errors_fp(stderr);
+    if (server_pid > 0) {
+        (void)kill(server_pid, SIGKILL);
+        while (waitpid(server_pid, NULL, 0) < 0 && errno == EINTR) { }
+    }
+    exit(2);
+}
+static void require(int condition, const char *label)
+{
+    if (!condition) fail(label);
+}
+static int64_t monotonic_us(void)
+{
+    struct timespec now;
+    require(clock_gettime(CLOCK_MONOTONIC, &now) == 0, "monotonic clock");
+    return (int64_t)now.tv_sec * 1000000 + now.tv_nsec / 1000;
+}
+static void message(int sending, int version, int content, const void *data,
+                    size_t size, SSL *ssl, void *arg)
+{
+    (void)version; (void)ssl; (void)arg;
+    if (!sending && content == SSL3_RT_HANDSHAKE && size &&
+        ((const unsigned char *)data)[0] == SSL3_MT_KEY_UPDATE) ++updates;
+}
+SSL *tls_budget_SSL_new(SSL_CTX *ctx)
+{
+    SSL *ssl = SSL_new(ctx);
+    observed_ssl = ssl;
+    if (ssl) SSL_set_msg_callback(ssl, message);
+    return ssl;
+}
+int tls_budget_SSL_read(SSL *ssl, void *bytes, int size)
+{
+    ++ssl_read_calls;
+    return SSL_read(ssl, bytes, size);
+}
+int tls_budget_SSL_write(SSL *ssl, const void *bytes, int size)
+{
+    if (inject_write_error) {
+        injected_error = inject_write_error;
+        inject_write_error = 0;
+        return -1;
+    }
+    return SSL_write(ssl, bytes, size);
+}
+int tls_budget_SSL_get_error(const SSL *ssl, int result)
+{
+    if (injected_error) {
+        int error = injected_error;
+        injected_error = 0;
+        return error;
+    }
+    return SSL_get_error(ssl, result);
+}
+static void send_all(int fd, const void *data, size_t size)
+{
+    const unsigned char *bytes = data;
+    while (size) {
+        ssize_t n = write(fd, bytes, size);
+        if (n < 0 && errno == EINTR) continue;
+        require(n > 0, "write all"); bytes += n; size -= (size_t)n;
+    }
+}
+static void read_all(int fd, void *data, size_t size)
+{
+    unsigned char *bytes = data;
+    while (size) {
+        ssize_t n = read(fd, bytes, size);
+        if (n < 0 && errno == EINTR) continue;
+        require(n > 0, "read all"); bytes += n; size -= (size_t)n;
+    }
+}
+static void signal_byte(int fd, char value) { send_all(fd, &value, 1); }
+static void expect_byte(int fd, char value)
+{
+    char got;
+    read_all(fd, &got, 1); require(got == value, "control marker");
+}
+static void ssl_send(SSL *ssl, const void *data, size_t size)
+{
+    const unsigned char *bytes = data;
+    while (size) {
+        int n = SSL_write(ssl, bytes, (int)size);
+        require(n > 0, "server TLS write"); bytes += n; size -= (size_t)n;
+    }
+}
+static void ssl_expect(SSL *ssl, const char *expected, size_t size)
+{
+    char bytes[1024];
+    require(size <= sizeof bytes, "server expected length");
+    size_t got = 0;
+    while (got < size) {
+        int n = SSL_read(ssl, bytes + got, (int)(size - got));
+        require(n > 0, "server TLS read"); got += (size_t)n;
+    }
+    require(!memcmp(bytes, expected, size), "server received exact reply");
+}
+static void key_update(SSL *ssl, int requested)
+{
+    require(SSL_key_update(ssl, requested) == 1, "server key update");
+    require(SSL_do_handshake(ssl) == 1, "server key update flush");
+}
+static void server_body(int listener, int control, int status,
+                         const char *cert, const char *key, unsigned offered)
+{
+    SSL_CTX *ctx = SSL_CTX_new(TLS_server_method());
+    SSL *ssl;
+    int sock = accept(listener, NULL, NULL), large = 4 * 1024 * 1024;
+    unsigned char bytes[65536];
+    alarm(25);
+    require(sock >= 0, "accept"); close(listener);
+    require(setsockopt(sock, SOL_SOCKET, SO_SNDBUF, &large, sizeof large) == 0, "server send buffer");
+    int version = strstr(scenario, "12") ? TLS1_2_VERSION : TLS1_3_VERSION;
+    require(ctx != NULL, "server context");
+    require(SSL_CTX_set_min_proto_version(ctx, version) == 1, "server TLS minimum");
+    require(SSL_CTX_set_max_proto_version(ctx, version) == 1, "server TLS maximum");
+    require(SSL_CTX_use_certificate_file(ctx, cert, SSL_FILETYPE_PEM) == 1, "server certificate");
+    require(SSL_CTX_use_PrivateKey_file(ctx, key, SSL_FILETYPE_PEM) == 1, "server private key");
+    require(SSL_CTX_set_num_tickets(ctx, 0) == 1, "server ticket count");
+    ssl = SSL_new(ctx); require(ssl != NULL, "server SSL");
+    require(SSL_set_fd(ssl, sock) == 1, "server socket BIO");
+    require(SSL_accept(ssl) == 1, "verified TLS server handshake");
+    signal_byte(status, 'R'); expect_byte(control, 'S');
+    if (!strcmp(scenario, "budget")) {
+        for (unsigned i = 0; i < offered; ++i) key_update(ssl, SSL_KEY_UPDATE_NOT_REQUESTED);
+        ssl_send(ssl, ping, sizeof ping - 1);
+        signal_byte(status, 'K');
+        ssl_expect(ssl, pong, sizeof pong - 1);
+        signal_byte(status, 'A');
+    } else if (!strcmp(scenario, "coalesced")) {
+        BIO *output = BIO_new(BIO_s_mem()); char *wire;
+        require(output != NULL, "memory output"); SSL_set0_wbio(ssl, output);
+        key_update(ssl, SSL_KEY_UPDATE_NOT_REQUESTED);
+        ssl_send(ssl, ping, sizeof ping - 1);
+        long length = BIO_get_mem_data(output, &wire);
+        require(length > (long)sizeof ping, "coalesced TLS records");
+        send_all(sock, wire, (size_t)length); signal_byte(status, 'K');
+        ssl_expect(ssl, pong, sizeof pong - 1); signal_byte(status, 'A');
+    } else if (!strncmp(scenario, "fragment", 8) || !strcmp(scenario, "truncated") || !strcmp(scenario, "corrupt")) {
+        BIO *output = BIO_new(BIO_s_mem()); char *wire;
+        require(output != NULL, "memory output"); SSL_set0_wbio(ssl, output);
+        for (size_t i = 0; i < 8192; ++i) bytes[i] = (unsigned char)(i % 251u);
+        ssl_send(ssl, bytes, 8192);
+        long length = BIO_get_mem_data(output, &wire);
+        require(length > 8192, "encrypted record length");
+        if (!strcmp(scenario, "corrupt")) wire[length - 1] ^= 1;
+        send_all(sock, wire, 7); signal_byte(status, 'F'); expect_byte(control, 'D');
+        if (!strcmp(scenario, "truncated")) {
+            SSL_free(ssl); SSL_CTX_free(ctx); close(sock); close(control); close(status); _exit(0);
+        }
+        send_all(sock, wire + 7, (size_t)length - 7); signal_byte(status, 'W');
+    } else {
+        int small = 4096;
+        require(setsockopt(sock, SOL_SOCKET, SO_RCVBUF, &small, sizeof small) == 0, "server receive buffer");
+        memset(bytes, 'I', 8192); ssl_send(ssl, bytes, 8192); signal_byte(status, 'I');
+        uint64_t expected, received = 0;
+        read_all(control, &expected, sizeof expected);
+        if (version == TLS1_3_VERSION) key_update(ssl, SSL_KEY_UPDATE_REQUESTED);
+        signal_byte(status, 'K'); expect_byte(control, 'D');
+        if (!strcmp(scenario, "reset-write")) {
+            struct linger reset = {1, 0};
+            require(setsockopt(sock, SOL_SOCKET, SO_LINGER, &reset, sizeof reset) == 0, "reset linger");
+            SSL_free(ssl); SSL_CTX_free(ctx); close(sock); close(control); close(status); _exit(0);
+        }
+        while (received < expected) {
+            int n = SSL_read(ssl, bytes, sizeof bytes);
+            require(n > 0, "server receives stalled stream");
+            for (int i = 0; i < n; ++i)
+                require(bytes[i] == (unsigned char)((received + (uint64_t)i) % 251u), "byte-exact stalled stream");
+            received += (uint64_t)n;
+        }
+        require(received == expected, "no duplicated stalled bytes");
+        ssl_send(ssl, "OK", 2);
+    }
+    expect_byte(control, 'Q');
+    SSL_free(ssl); SSL_CTX_free(ctx); close(sock); close(control); close(status); _exit(0);
+}
+typedef struct Fixture { Net *net; int control, status; } Fixture;
+static Fixture start(const char *cert, const char *key, unsigned offered)
+{
+    int listener = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP), control[2], status[2];
+    struct sockaddr_in addr;
+    socklen_t length = sizeof addr;
+    char error[512];
+    Fixture f;
+    require(listener >= 0, "listener");
+    memset(&addr, 0, sizeof addr); addr.sin_family = AF_INET; addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
+    require(bind(listener, (struct sockaddr *)&addr, sizeof addr) == 0, "loopback bind");
+    require(getsockname(listener, (struct sockaddr *)&addr, &length) == 0, "listener address");
+    require(listen(listener, 1) == 0, "listen");
+    require(pipe(control) == 0 && pipe(status) == 0, "control pipes");
+    server_pid = fork(); require(server_pid >= 0, "server fork");
+    if (!server_pid) { close(control[1]); close(status[0]); server_body(listener, control[0], status[1], cert, key, offered); }
+    close(listener); close(control[0]); close(status[1]);
+    f.control = control[1]; f.status = status[0];
+    f.net = net_open("127.0.0.1", ntohs(addr.sin_port), 1, cert, error, sizeof error);
+    require(f.net != NULL, error);
+    int64_t deadline = net_now_ms() + 8000;
+    while (net_state(f.net) != NET_READY && net_state(f.net) != NET_FAILED && net_now_ms() < deadline) {
+        struct pollfd p = {net_fd(f.net), net_events(f.net, 0), 0};
+        int n = poll(&p, 1, 50);
+        if (n < 0 && errno == EINTR) continue;
+        require(n >= 0, "setup poll"); (void)net_step(f.net, p.revents, net_now_ms());
+    }
+    require(net_state(f.net) == NET_READY, net_error(f.net));
+    require(SSL_get_verify_result(observed_ssl) == X509_V_OK, "certificate remains verified");
+    expect_byte(f.status, 'R'); signal_byte(f.control, 'S'); return f;
+}
+static short ready(Net *net, int write_pending, int timeout)
+{
+    struct pollfd p = {net_fd(net), net_events(net, write_pending), 0};
+    int n;
+    do { n = poll(&p, 1, net_pending(net) ? 0 : timeout); } while (n < 0 && errno == EINTR);
+    require(n >= 0, "transport poll");
+    require(net_step(net, p.revents, net_now_ms()) == 0, net_error(net));
+    return p.revents;
+}
+static void reply(Fixture *f)
+{
+    size_t sent = 0;
+    int64_t deadline = net_now_ms() + 5000;
+    while (sent < sizeof pong - 1 && net_now_ms() < deadline) {
+        (void)ready(f->net, 1, 50);
+        ssize_t n = net_write(f->net, pong + sent, sizeof pong - 1 - sent);
+        if (n == -2) continue;
+        require(n > 0, net_error(f->net)); sent += (size_t)n;
+    }
+    require(sent == sizeof pong - 1, "PONG reply progress"); expect_byte(f->status, 'A');
+}
+static int budget(Fixture *f, unsigned offered)
+{
+    char bytes[sizeof ping]; size_t received = 0;
+    unsigned calls = 0, maximum_updates = 0, first_updates = 0, timers = 0;
+    int64_t first_us = 0, max_us = 0, maximum_timer_late_us = 0;
+    expect_byte(f->status, 'K');
+    int64_t started = monotonic_us(), next_timer = started + 10000, deadline = started + 15000000;
+    while (received < sizeof ping - 1 && monotonic_us() < deadline) {
+        short events = ready(f->net, 0, 10);
+        if (!events && !net_pending(f->net)) continue;
+        unsigned before_updates = updates;
+        int64_t before = monotonic_us();
+        ssize_t n = net_read(f->net, bytes + received, sizeof ping - 1 - received);
+        int64_t now = monotonic_us(), duration = now - before;
+        unsigned processed = updates - before_updates;
+        if (!calls) { first_us = duration; first_updates = processed; }
+        ++calls; if (processed > maximum_updates) maximum_updates = processed;
+        if (duration > max_us) max_us = duration;
+        if (now >= next_timer) {
+            if (now - next_timer > maximum_timer_late_us) maximum_timer_late_us = now - next_timer;
+            ++timers; next_timer = now + 10000;
+        }
+        if (n == -2) continue;
+        require(n > 0, net_error(f->net)); received += (size_t)n;
+    }
+    require(received == sizeof ping - 1 && !memcmp(bytes, ping, sizeof ping - 1), "exact final PING delivered");
+    require(updates == offered, "all offered control records processed"); reply(f);
+    printf("{\"case\":\"budget\",\"offered\":%u,\"read_calls\":%u,\"first_updates\":%u,\"max_updates_per_read\":%u,\"first_read_us\":%lld,\"max_read_us\":%lld,\"timer_callbacks\":%u,\"max_timer_late_us\":%lld,\"ping_pong\":true}\n",
+           offered, calls, first_updates, maximum_updates, (long long)first_us, (long long)max_us, timers, (long long)maximum_timer_late_us);
+    return maximum_updates <= 1 ? 0 : 1;
+}
+static int coalesced(Fixture *f)
+{
+    char bytes[sizeof ping];
+    expect_byte(f->status, 'K'); (void)ready(f->net, 0, 1000);
+    ssize_t first = net_read(f->net, bytes, sizeof bytes);
+    int decoded = net_pending(f->net), buffered = SSL_has_pending(observed_ssl);
+    struct pollfd p = {net_fd(f->net), POLLIN, 0};
+    require(poll(&p, 1, 0) >= 0, "coalesced poll");
+    int bounded = first == -2 && updates == 1 && decoded == 0 && (p.revents & POLLIN);
+    ssize_t n = first > 0 ? first : net_read(f->net, bytes, sizeof bytes);
+    require(n == (ssize_t)(sizeof ping - 1) && !memcmp(bytes, ping, sizeof ping - 1), "coalesced PING progress"); reply(f);
+    printf("{\"case\":\"coalesced\",\"first_read\":%zd,\"decoded_after_yield\":%d,\"has_pending_after_yield\":%d,\"socket_still_readable\":%s,\"ping_pong\":true}\n",
+           first, decoded, buffered, p.revents & POLLIN ? "true" : "false");
+    return bounded ? 0 : 1;
+}
+static int fragment(Fixture *f)
+{
+    unsigned char bytes[8192]; size_t got = 0;
+    expect_byte(f->status, 'F'); (void)ready(f->net, 0, 1000);
+    require(net_read(f->net, bytes, 73) == -2, "partial TLS record is not application data");
+    require(net_pending(f->net) == 0, "partial ciphertext cannot force zero timeout");
+    int buffered = SSL_has_pending(observed_ssl);
+    int64_t before = monotonic_us();
+    require(ready(f->net, 0, 80) == 0, "partial record waits for network data");
+    int64_t waited = monotonic_us() - before;
+    require(waited >= 50000, "no partial-record busy poll");
+    signal_byte(f->control, 'D');
+    if (strcmp(scenario, "truncated")) expect_byte(f->status, 'W');
+    if (!strcmp(scenario, "truncated") || !strcmp(scenario, "corrupt")) {
+        ssize_t n = -2;
+        int64_t deadline = net_now_ms() + 5000;
+        while (n == -2 && net_now_ms() < deadline) { (void)ready(f->net, 0, 100); n = net_read(f->net, bytes, sizeof bytes); }
+        int retry = !strcmp(scenario, "truncated");
+        require(n == -1 && net_state(f->net) == NET_FAILED && net_retryable(f->net) == retry,
+                "truncated/corrupt TLS record fails with correct retry policy");
+        printf("{\"case\":\"%s\",\"partial_has_pending\":%d,\"idle_wait_us\":%lld,\"returned_application_bytes\":0,\"retryable\":%s}\n", scenario, buffered, (long long)waited, retry ? "true" : "false");
+        return 0;
+    }
+    int saw_buffer_without_readiness = 0;
+    int64_t deadline = net_now_ms() + 5000;
+    while (got < sizeof bytes && net_now_ms() < deadline) {
+        short events = ready(f->net, 0, 100);
+        if (net_pending(f->net) && !events) saw_buffer_without_readiness = 1;
+        ssize_t n = net_read(f->net, bytes + got, sizeof bytes - got < 73 ? sizeof bytes - got : 73);
+        if (n == -2) continue;
+        require(n > 0, net_error(f->net)); got += (size_t)n;
+    }
+    require(got == sizeof bytes, "all fragmented plaintext delivered");
+    for (size_t i = 0; i < got; ++i) require(bytes[i] == (unsigned char)(i % 251u), "fragmented plaintext integrity");
+    require(saw_buffer_without_readiness && net_pending(f->net) == 0, "decoded TLS bytes drain without fresh socket event");
+    printf("{\"case\":\"%s\",\"partial_has_pending\":%d,\"idle_wait_us\":%lld,\"decoded_drain_without_socket_event\":true,\"bytes\":%zu}\n", scenario, buffered, (long long)waited, got);
+    return 0;
+}
+static int write_priority(Fixture *f)
+{
+    unsigned char bytes[65536], incoming[8194];
+    size_t sent = 0, incoming_size = 0, pending_done = 0;
+    ssize_t n;
+    expect_byte(f->status, 'I'); (void)ready(f->net, 0, 1000);
+    n = net_read(f->net, incoming, 1);
+    require(n == 1 && incoming[0] == 'I', "prime decoded read buffer"); incoming_size = 1;
+    require(net_pending(f->net) == 8191, "decoded bytes initially readable");
+    int injected = !strcmp(scenario, "want-read");
+    if (injected) {
+        for (size_t i = 0; i < sizeof bytes; ++i) bytes[i] = (unsigned char)(i % 251u);
+        inject_write_error = SSL_ERROR_WANT_READ;
+        require(net_write(f->net, bytes, sizeof bytes) == -2, "injected write needs read");
+    } else {
+        int small = 4096;
+        require(setsockopt(net_fd(f->net), SOL_SOCKET, SO_SNDBUF, &small, sizeof small) == 0, "client send buffer");
+        for (unsigned i = 0; i < 1024; ++i) {
+            for (size_t j = 0; j < sizeof bytes; ++j) bytes[j] = (unsigned char)((sent + j) % 251u);
+            n = net_write(f->net, bytes, sizeof bytes);
+            if (n == -2) break;
+            require(n > 0, net_error(f->net)); sent += (size_t)n;
+        }
+        require(n == -2, "real TLS write backpressure reached");
+    }
+    unsigned before_calls = ssl_read_calls;
+    int eligible = net_pending(f->net), internal = SSL_pending(observed_ssl);
+    short events = net_events(f->net, 1);
+    n = net_read(f->net, incoming + incoming_size, 1);
+    int precedence = injected ? n == 1 && ssl_read_calls == before_calls + 1 && eligible == internal && (events & POLLIN) :
+                               n == -2 && ssl_read_calls == before_calls && eligible == 0 && events == POLLOUT;
+    if (n > 0) incoming_size += (size_t)n;
+    uint64_t expected = sent + sizeof bytes;
+    send_all(f->control, &expected, sizeof expected); expect_byte(f->status, 'K'); signal_byte(f->control, 'D');
+    int64_t deadline = net_now_ms() + 8000;
+    while (pending_done < sizeof bytes && net_now_ms() < deadline) {
+        (void)ready(f->net, 1, 50);
+        n = net_write(f->net, bytes + pending_done, sizeof bytes - pending_done);
+        if (n == -2) continue;
+        if (!strcmp(scenario, "reset-write")) break;
+        require(n > 0, net_error(f->net)); pending_done += (size_t)n;
+    }
+    if (!strcmp(scenario, "reset-write")) {
+        require(n == -1 && net_state(f->net) == NET_FAILED && net_retryable(f->net), "blocked write reset terminates with transient classification");
+        printf("{\"case\":\"reset-write\",\"precedence_correct\":%s,\"failed_boundedly\":true,\"retryable\":true}\n", precedence ? "true" : "false");
+        return precedence ? 0 : 1;
+    }
+    require(pending_done == sizeof bytes, "stalled write completes with same retry bytes");
+    while (incoming_size < sizeof incoming && net_now_ms() < deadline) {
+        short revents = ready(f->net, 0, 50);
+        if (!revents && !net_pending(f->net)) continue;
+        n = net_read(f->net, incoming + incoming_size, sizeof incoming - incoming_size);
+        if (n == -2) continue;
+        require(n > 0, net_error(f->net)); incoming_size += (size_t)n;
+    }
+    require(incoming_size == sizeof incoming, "deferred input and acknowledgement delivered");
+    for (size_t i = 0; i < 8192; ++i) require(incoming[i] == 'I', "deferred input integrity");
+    require(!memcmp(incoming + 8192, "OK", 2), "stream acknowledgement");
+    printf("{\"case\":\"%s\",\"injected_want_read\":%s,\"precedence_correct\":%s,\"pending_internal\":%d,\"pending_eligible\":%d,\"poll_events\":%d,\"sent\":%llu,\"received\":%zu}\n",
+           scenario, injected ? "true" : "false", precedence ? "true" : "false", internal, eligible, (int)events, (unsigned long long)expected, incoming_size);
+    return precedence ? 0 : 1;
+}
+int main(int argc, char **argv)
+{
+    require(argc == 5, "arguments: certificate key scenario updates");
+    scenario = argv[3];
+    unsigned offered = (unsigned)strtoul(argv[4], NULL, 10);
+    require(offered > 0 && offered <= 100000, "bounded fixture update count");
+    signal(SIGPIPE, SIG_IGN); alarm(30);
+    Fixture f = start(argv[1], argv[2], offered);
+    int result;
+    if (!strcmp(scenario, "budget")) result = budget(&f, offered);
+    else if (!strcmp(scenario, "coalesced")) result = coalesced(&f);
+    else if (!strncmp(scenario, "fragment", 8) || !strcmp(scenario, "truncated") || !strcmp(scenario, "corrupt")) result = fragment(&f);
+    else result = write_priority(&f);
+    if (strcmp(scenario, "truncated") && strcmp(scenario, "reset-write")) signal_byte(f.control, 'Q');
+    net_close(f.net); close(f.control); close(f.status);
+    int status; pid_t found;
+    do { found = waitpid(server_pid, &status, 0); } while (found < 0 && errno == EINTR);
+    require(found == server_pid, "server collection"); server_pid = 0;
+    require(WIFEXITED(status) && WEXITSTATUS(status) == 0, "server successful exit");
+    return result;
+}

vipirc-0.7.28.tests/test_presence_cancellation.c:
--- vipirc-0.7.27/tests/test_presence_cancellation.c
+++ vipirc-0.7.28/tests/test_presence_cancellation.c
@@ -0,0 +1,242 @@
+/* Ordinary automatic-command cancellation through the real application.
+ * The shared fixture supplies only an in-memory transport and fake clock. */
+#define main legacy_app_test_main
+#include "test_app.c"
+#undef main
+
+static void hold_control(App *a)
+{
+    assert(app_outgoing(a, 0, "PING :hold-control"));
+    a->net->block = 1;
+    app_network(a, 0);
+    assert(a->inflight && a->net->retry && !a->net->output_len);
+}
+
+static void cancel_script_away(void)
+{
+    App *a = fresh_automatic("/away Scheduled absence", "/whois later", 1);
+    SendPlan plan;
+    register_plain(a);
+    output_clear(a);
+    hold_control(a);
+    clock_ms += 1000;
+    app_network(a, 0);
+    assert(a->autocommand_waiting && a->control_count == 1);
+    assert(a->manual_away_pending && !a->away);
+    assert(app_command(a, "/cancel", &plan) == 1);
+    assert(!a->autocommand_active && !a->control_count && a->inflight);
+    if (a->manual_away_pending) {
+        puts("FAIL: cancelling an unsent automatic AWAY leaves manual_away_pending set");
+        fflush(stdout);
+    }
+    assert(!a->manual_away_pending);
+    a->cfg.background_away = 1;
+    strcpy(a->cfg.background_away_message, "Detached");
+    app_set_backgrounded(a, 1);
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\nAWAY :Detached\r\n"));
+    assert(a->automatic_away == APP_AUTO_AWAY_BACKGROUND);
+    destroy(a);
+}
+
+static void cancel_script_back(void)
+{
+    App *a = fresh_automatic("/back", "/whois later", 1);
+    SendPlan plan;
+    register_plain(a);
+    output_clear(a);
+    hold_control(a);
+    assert(app_command(a, "/away Earlier manual", &plan) == 1);
+    clock_ms += 1000;
+    app_network(a, 0);
+    assert(a->autocommand_waiting && a->control_count == 2);
+    assert(!a->manual_away_pending);
+    assert(app_autocommands_cancel(a) == 2);
+    if (!a->manual_away_pending) {
+        puts("FAIL: cancelling an unsent script BACK loses the earlier manual AWAY intent");
+        fflush(stdout);
+    }
+    assert(a->manual_away_pending);
+    a->cfg.background_away = 1;
+    strcpy(a->cfg.background_away_message, "Detached");
+    app_set_backgrounded(a, 1);
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\nAWAY :Earlier manual\r\n"));
+    feed(a, ":server 306 tester :Away\r\n");
+    assert(a->away && !a->manual_away_pending && a->automatic_away == APP_AUTO_AWAY_NONE);
+    destroy(a);
+}
+
+static void cancel_restores_idle_away(void)
+{
+    App *a = fresh_automatic("/away Scheduled absence", NULL, 2);
+    SendPlan plan;
+    register_plain(a);
+    a->cfg.autoaway_minutes = 1;
+    strcpy(a->cfg.autoaway_message, "Idle");
+    a->last_local_activity = clock_ms - 60000;
+    app_network(a, 0);
+    feed(a, ":server 306 tester :Away\r\n");
+    assert(a->away && a->automatic_away == APP_AUTO_AWAY_IDLE);
+    output_clear(a);
+    hold_control(a);
+    clock_ms += 2000;
+    app_network(a, 0);
+    assert(a->manual_away_pending && a->automatic_away == APP_AUTO_AWAY_NONE);
+    app_user_activity(a);
+    assert(app_command(a, "/cancel", &plan) == 1);
+    assert(!a->manual_away_pending && a->automatic_away == APP_AUTO_AWAY_IDLE);
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\nAWAY\r\n"));
+    assert(a->automatic_away == APP_AUTO_AWAY_NONE);
+    destroy(a);
+}
+
+static void newer_manual_intent(void)
+{
+    static const char *const newer[] = {"/away Newer manual", "/back"};
+    for (size_t i = 0; i < sizeof newer / sizeof newer[0]; ++i) {
+        App *a = fresh_automatic("/back", NULL, 1);
+        SendPlan plan;
+        register_plain(a);
+        output_clear(a);
+        hold_control(a);
+        assert(app_command(a, "/away Earlier manual", &plan) == 1);
+        clock_ms += 1000;
+        app_network(a, 0);
+        assert(a->autocommand_waiting && !a->manual_away_pending);
+        assert(app_command(a, newer[i], &plan) == 1);
+        assert(app_autocommands_cancel(a) == 1);
+        assert(a->manual_away_pending == (i == 0));
+        assert(a->automatic_away == APP_AUTO_AWAY_NONE);
+        a->net->block = 0;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, i == 0 ?
+            "PING :hold-control\r\nAWAY :Earlier manual\r\nAWAY :Newer manual\r\n" :
+            "PING :hold-control\r\nAWAY :Earlier manual\r\nAWAY\r\n"));
+        destroy(a);
+    }
+}
+
+static void newer_server_confirmation(void)
+{
+    App *a = fresh_automatic("/back", NULL, 1);
+    SendPlan plan;
+    register_plain(a);
+    assert(app_command(a, "/away Earlier manual", &plan) == 1);
+    app_network(a, 0);
+    assert(a->manual_away_pending);
+    output_clear(a);
+    hold_control(a);
+    clock_ms += 1000;
+    app_network(a, 0);
+    assert(a->autocommand_waiting && !a->manual_away_pending);
+    feed(a, ":server 306 tester :Earlier manual confirmed\r\n");
+    assert(a->away && !a->manual_away_pending);
+    assert(app_autocommands_cancel(a) == 1);
+    assert(a->away && !a->manual_away_pending);
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+    destroy(a);
+}
+
+static void inflight_script_presence(void)
+{
+    for (int partial = 0; partial <= 1; ++partial) {
+        App *a = fresh_automatic("/away Scheduled absence", "/whois later", 1);
+        register_plain(a);
+        output_clear(a);
+        if (partial) a->net->write_limit = 3;
+        else a->net->block = 1;
+        clock_ms += 1000;
+        app_network(a, 0);
+        assert(a->inflight && a->autocommand_waiting && a->manual_away_pending);
+        assert(a->net->output_len == (partial ? 3u : 0u));
+        assert(app_autocommands_cancel(a) == 1);
+        assert(a->inflight && a->manual_away_pending);
+        a->net->block = 0;
+        a->net->write_limit = 0;
+        app_network(a, 0);
+        assert(!a->inflight && !a->autocommand_active && a->manual_away_pending);
+        assert(!strcmp(a->net->output, "AWAY :Scheduled absence\r\n"));
+        feed(a, ":server 306 tester :Away\r\n");
+        assert(a->away && !a->manual_away_pending);
+        clock_ms += 5000;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, "AWAY :Scheduled absence\r\n"));
+        destroy(a);
+    }
+}
+
+static void reject_unsent_script_presence(void)
+{
+    App *a = fresh_automatic("/away Scheduled absence message longer than the newly advertised limit for this connection", NULL, 1);
+    register_plain(a);
+    output_clear(a);
+    hold_control(a);
+    clock_ms += 1000;
+    app_network(a, 0);
+    assert(a->manual_away_pending && a->control_count == 1);
+    feed(a, ":server 005 tester LINELEN=64 :supported\r\n");
+    assert(a->control_count == 1 && a->manual_away_pending);
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!a->autocommand_active && !a->manual_away_pending);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+    a->cfg.background_away = 1;
+    strcpy(a->cfg.background_away_message, "Detached");
+    app_set_backgrounded(a, 1);
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\nAWAY :Detached\r\n"));
+    destroy(a);
+}
+
+static void disconnect_clears_presence(void)
+{
+    App *a = fresh_automatic("/away Scheduled absence", NULL, 1);
+    register_plain(a);
+    output_clear(a);
+    hold_control(a);
+    clock_ms += 1000;
+    app_network(a, 0);
+    assert(a->manual_away_pending && a->control_count == 1);
+    app_disconnect(a, "Reconnect fixture");
+    assert(!a->manual_away_pending && a->automatic_away == APP_AUTO_AWAY_NONE);
+    assert(!app_autocommands_cancel(a));
+    assert(!a->manual_away_pending && !a->control_head && !a->inflight);
+    assert(app_connect(a));
+    app_network(a, 0);
+    register_plain(a);
+    output_clear(a);
+    assert(app_autocommands_cancel(a) == 1 && !a->autocommand_active);
+    a->cfg.background_away = 1;
+    strcpy(a->cfg.background_away_message, "Detached");
+    app_set_backgrounded(a, 1);
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "AWAY :Detached\r\n"));
+    destroy(a);
+}
+
+int main(int argc, char **argv)
+{
+    static const struct { const char *name; void (*run)(void); } cases[] = {
+        {"queued-away", cancel_script_away}, {"queued-back", cancel_script_back},
+        {"restore-idle", cancel_restores_idle_away}, {"newer-manual", newer_manual_intent},
+        {"server-confirmation", newer_server_confirmation}, {"inflight", inflight_script_presence},
+        {"reject-unsent", reject_unsent_script_presence}, {"reconnect", disconnect_clears_presence}
+    };
+    int matched = 0;
+    assert(argc == 1 || argc == 2);
+    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i)
+        if (argc == 1 || !strcmp(argv[1], cases[i].name)) {
+            cases[i].run();
+            printf("presence cancellation: %s passed\n", cases[i].name);
+            matched = 1;
+        }
+    assert(matched);
+    return 0;
+}

vipirc-0.7.28.tests/test_presence_recovery.c:
--- vipirc-0.7.27/tests/test_presence_recovery.c
+++ vipirc-0.7.28/tests/test_presence_recovery.c
@@ -0,0 +1,458 @@
+/* Local return and newer presence intent under ordinary control-queue pressure.
+ * The shared fixture supplies an in-memory transport and a fake clock. */
+#define main legacy_app_test_main
+#include "test_app.c"
+#undef main
+
+static size_t full_queue_notices;
+
+static void observe_full_queue(void *context, const App *a, const char *text)
+{
+    (void)context;
+    (void)a;
+    if (strstr(text, "Outgoing queue is full")) ++full_queue_notices;
+}
+
+static void fill_control_queue(App *a)
+{
+    for (size_t i = 0; i < APP_QUEUE; ++i)
+        assert(app_outgoing(a, 0, "PING :queued-control-%zu", i));
+}
+
+static void drain_control_queue(App *a)
+{
+    for (size_t i = 0; i < 3 && (a->inflight || a->control_count); ++i)
+        app_network(a, 0);
+    assert(!a->inflight && !a->control_count);
+}
+
+static App *failed_return(int background, int confirmed)
+{
+    App *a = fresh(0);
+    register_plain(a);
+    if (background) {
+        a->cfg.background_away = 1;
+        strcpy(a->cfg.background_away_message, "Detached");
+        app_set_backgrounded(a, 1);
+    } else {
+        a->cfg.autoaway_minutes = 1;
+        strcpy(a->cfg.autoaway_message, "Idle");
+        a->last_local_activity = clock_ms - 60000;
+    }
+    app_network(a, 0);
+    if (confirmed) feed(a, ":server 306 tester :Away\r\n");
+    assert(a->automatic_away == (background ? APP_AUTO_AWAY_BACKGROUND : APP_AUTO_AWAY_IDLE));
+    output_clear(a);
+    full_queue_notices = 0;
+    a->status_event = observe_full_queue;
+    fill_control_queue(a);
+    if (background) app_set_backgrounded(a, 0);
+    else app_user_activity(a);
+    assert(full_queue_notices == 1 && a->control_count == APP_QUEUE);
+    return a;
+}
+
+static void bounded_clear_retry(void)
+{
+    for (int background = 0; background <= 1; ++background) {
+        App *a = failed_return(background, 1);
+        a->net->block = 1;
+        for (size_t i = 0; i < 100; ++i) app_network(a, 0);
+        assert(full_queue_notices == 1 && app_timeout(a) == 1000);
+        clock_ms += 1000;
+        app_network(a, 0);
+        assert(full_queue_notices == 2);
+        for (size_t i = 0; i < 100; ++i) app_network(a, 0);
+        assert(full_queue_notices == 2 && app_timeout(a) == 1000);
+        a->net->block = 0;
+        drain_control_queue(a);
+        output_clear(a);
+        clock_ms += 999;
+        app_network(a, 0);
+        assert(!a->net->output_len && app_timeout(a) == 1);
+        ++clock_ms;
+        assert(app_timeout(a) == 0);
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, "AWAY\r\n"));
+        assert(a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+        feed(a, ":server 305 tester :Back\r\n");
+        clock_ms += 5000;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, "AWAY\r\n"));
+        assert(!a->away);
+        destroy(a);
+    }
+}
+
+static void newer_manual_presence(void)
+{
+    static const char *const commands[] = {"/away Manual replacement", "/back"};
+    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; ++i) {
+        App *a = failed_return(1, 1);
+        SendPlan plan;
+        drain_control_queue(a);
+        output_clear(a);
+        assert(app_command(a, commands[i], &plan) == 1);
+        app_network(a, 0);
+        feed(a, i == 0 ? ":server 306 tester :Manual away\r\n" : ":server 305 tester :Back\r\n");
+        clock_ms += 5000;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, i == 0 ? "AWAY :Manual replacement\r\n" : "AWAY\r\n"));
+        assert(!a->automatic_away_retry_at && a->automatic_away == APP_AUTO_AWAY_NONE);
+        destroy(a);
+    }
+}
+
+static void renewed_background_presence(void)
+{
+    App *a = failed_return(1, 1);
+    app_set_backgrounded(a, 1);
+    assert(a->control_count == APP_QUEUE);
+    drain_control_queue(a);
+    output_clear(a);
+    clock_ms += 5000;
+    app_network(a, 0);
+    assert(!a->net->output_len && a->automatic_away == APP_AUTO_AWAY_BACKGROUND);
+    assert(!a->automatic_away_retry_at);
+    app_set_backgrounded(a, 0);
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "AWAY\r\n"));
+    destroy(a);
+}
+
+static void server_presence_confirmation(void)
+{
+    for (int away = 0; away <= 1; ++away) {
+        App *a = failed_return(1, 0);
+        a->net->block = 1;
+        feed(a, away ? ":server 306 tester :Old away confirmed\r\n" : ":server 305 tester :Already back\r\n");
+        a->net->block = 0;
+        drain_control_queue(a);
+        output_clear(a);
+        clock_ms += 1000;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, away ? "AWAY\r\n" : ""));
+        assert(a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+        destroy(a);
+    }
+}
+
+/* Registration starts the script's one-second delay. Local return occurs half
+ * a second later, so a queued script can supersede a not-yet-due clear retry. */
+static App *script_over_clear(const char *command)
+{
+    App *a = fresh_automatic(command, NULL, 1);
+    register_plain(a);
+    a->cfg.background_away = 1;
+    strcpy(a->cfg.background_away_message, "Detached");
+    app_set_backgrounded(a, 1);
+    app_network(a, 0);
+    feed(a, ":server 306 tester :Away\r\n");
+    output_clear(a);
+    clock_ms += 500;
+    fill_control_queue(a);
+    app_set_backgrounded(a, 0);
+    drain_control_queue(a);
+    output_clear(a);
+    assert(app_outgoing(a, 0, "PING :hold-control"));
+    a->net->block = 1;
+    app_network(a, 0);
+    clock_ms += 500;
+    app_network(a, 0);
+    assert(a->autocommand_waiting && a->inflight && a->control_count == 1);
+    return a;
+}
+
+static void newer_script_presence(void)
+{
+    static const char *const commands[] = {"/away Script replacement", "/back"};
+    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; ++i) {
+        App *a = script_over_clear(commands[i]);
+        a->net->block = 0;
+        app_network(a, 0);
+        feed(a, i == 0 ? ":server 306 tester :Script away\r\n" : ":server 305 tester :Back\r\n");
+        clock_ms += 5000;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, i == 0 ?
+            "PING :hold-control\r\nAWAY :Script replacement\r\n" : "PING :hold-control\r\nAWAY\r\n"));
+        assert(!a->automatic_away_retry_at && a->automatic_away == APP_AUTO_AWAY_NONE);
+        destroy(a);
+    }
+}
+
+static void cancelled_script_restores_clear(void)
+{
+    static const char *const commands[] = {"/away Script replacement", "/back"};
+    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; ++i) {
+        App *a = script_over_clear(commands[i]);
+        assert(app_autocommands_cancel(a) == 1);
+        a->net->block = 0;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+        assert(a->automatic_away == APP_AUTO_AWAY_BACKGROUND && app_timeout(a) == 500);
+        clock_ms += 499;
+        app_network(a, 0);
+        assert(app_timeout(a) == 1);
+        assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+        ++clock_ms;
+        app_network(a, 0);
+        assert(!strcmp(a->net->output, "PING :hold-control\r\nAWAY\r\n"));
+        assert(a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+        destroy(a);
+    }
+}
+
+static void rejected_script_restores_clear(void)
+{
+    App *a = script_over_clear("/away Scheduled absence message longer than the newly advertised limit for this connection");
+    feed(a, ":server 005 tester LINELEN=64 :supported\r\n");
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+    assert(!a->autocommand_active && app_timeout(a) == 500);
+    clock_ms += 500;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\nAWAY\r\n"));
+    destroy(a);
+}
+
+static void background_after_script_cancel(void)
+{
+    App *a = script_over_clear("/away Script replacement");
+    app_set_backgrounded(a, 1);
+    assert(app_autocommands_cancel(a) == 1);
+    a->net->block = 0;
+    app_network(a, 0);
+    clock_ms += 5000;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+    assert(a->automatic_away == APP_AUTO_AWAY_BACKGROUND && !a->automatic_away_retry_at);
+    destroy(a);
+}
+
+static void old_confirmation_during_script(void)
+{
+    static const char *const commands[] = {"/away Script replacement", "/back"};
+    for (int away = 1; away >= 0; --away) {
+        for (size_t i = 0; i < sizeof commands / sizeof commands[0]; ++i) {
+            App *a = script_over_clear(commands[i]);
+            feed(a, away ? ":server 306 tester :Earlier away confirmed\r\n" :
+                           ":server 305 tester :Earlier clear confirmed\r\n");
+            assert(a->manual_away_pending == (i == 0));
+            assert(app_autocommands_cancel(a) == 1);
+            a->net->block = 0;
+            app_network(a, 0);
+            assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+            assert(!a->manual_away_pending);
+            if (away) assert(a->automatic_away == APP_AUTO_AWAY_BACKGROUND && app_timeout(a) == 500);
+            else assert(a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+            clock_ms += 500;
+            app_network(a, 0);
+            assert(!strcmp(a->net->output, away ? "PING :hold-control\r\nAWAY\r\n" :
+                                                       "PING :hold-control\r\n"));
+            destroy(a);
+        }
+    }
+}
+
+static void manual_confirmation_during_script(void)
+{
+    static const char *const commands[] = {"/away Script replacement", "/back"};
+    static const char *const earlier[] = {"/away Earlier manual", "/back"};
+    for (size_t prior = 0; prior < sizeof earlier / sizeof earlier[0]; ++prior) {
+        for (int away = 0; away <= 1; ++away) {
+            for (size_t i = 0; i < sizeof commands / sizeof commands[0]; ++i) {
+                App *a = fresh_automatic(commands[i], NULL, 1);
+                SendPlan plan;
+                register_plain(a);
+                assert(app_command(a, earlier[prior], &plan) == 1);
+                app_network(a, 0);
+                output_clear(a);
+                assert(app_outgoing(a, 0, "PING :hold-control"));
+                a->net->block = 1;
+                app_network(a, 0);
+                clock_ms += 1000;
+                app_network(a, 0);
+                feed(a, away ? ":server 306 tester :Earlier away confirmed\r\n" :
+                               ":server 305 tester :Earlier clear confirmed\r\n");
+                assert(a->manual_away_pending == (i == 0));
+                assert(app_autocommands_cancel(a) == 1);
+                assert(a->away == away && a->manual_away_pending == (!away && prior == 0));
+                assert(a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+                a->net->block = 0;
+                app_network(a, 0);
+                clock_ms += 5000;
+                app_network(a, 0);
+                assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+                destroy(a);
+            }
+        }
+    }
+}
+
+static void foreground_while_script_pending(void)
+{
+    static const char *const commands[] = {
+        "/away Script replacement", "/back",
+        "/away Scheduled absence message longer than the newly advertised limit for this connection"
+    };
+    for (int outcome = 0; outcome < 4; ++outcome) {
+        for (size_t i = 0; i < sizeof commands / sizeof commands[0]; ++i) {
+            App *a = fresh_automatic(commands[i], NULL, 2);
+            register_plain(a);
+            a->cfg.background_away = 1;
+            strcpy(a->cfg.background_away_message, "Detached");
+            app_set_backgrounded(a, 1);
+            app_network(a, 0);
+            feed(a, ":server 306 tester :Away\r\n");
+            output_clear(a);
+            assert(app_outgoing(a, 0, "PING :hold-control"));
+            a->net->block = 1;
+            app_network(a, 0);
+            clock_ms += 2000;
+            app_network(a, 0);
+            assert(a->autocommand_waiting && a->control_count == 1);
+            app_set_backgrounded(a, 0);
+            assert(a->manual_away_pending == (i != 1));
+            if (outcome == 1) feed(a, ":server 305 tester :Already back\r\n");
+            if (outcome == 2) feed(a, ":server 306 tester :Earlier away confirmed\r\n");
+            if (outcome == 3) app_set_backgrounded(a, 1);
+            if (i == 2) feed(a, ":server 005 tester LINELEN=64 :supported\r\n");
+            else assert(app_autocommands_cancel(a) == 1);
+            a->net->block = 0;
+            app_network(a, 0);
+            int cleared = outcome == 0 || outcome == 2;
+            assert(!strcmp(a->net->output, cleared ? "PING :hold-control\r\nAWAY\r\n" :
+                                                    "PING :hold-control\r\n"));
+            assert(!a->manual_away_pending && !a->automatic_away_retry_at);
+            assert(a->automatic_away == (outcome == 3 ? APP_AUTO_AWAY_BACKGROUND : APP_AUTO_AWAY_NONE));
+            destroy(a);
+        }
+    }
+}
+
+static void activity_preserves_prior_manual_away(void)
+{
+    App *a = fresh_automatic("/away Script replacement", NULL, 1);
+    SendPlan plan;
+    register_plain(a);
+    assert(app_command(a, "/away Earlier manual", &plan) == 1);
+    app_network(a, 0);
+    feed(a, ":server 306 tester :Manual away\r\n");
+    output_clear(a);
+    assert(app_outgoing(a, 0, "PING :hold-control"));
+    a->net->block = 1;
+    app_network(a, 0);
+    clock_ms += 1000;
+    app_network(a, 0);
+    app_user_activity(a);
+    assert(app_command(a, "/cancel", &plan) == 1);
+    a->net->block = 0;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "PING :hold-control\r\n"));
+    assert(a->away && a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+    destroy(a);
+}
+
+static void stale_back_confirmation_after_away(void)
+{
+    for (int script = 0; script <= 1; ++script) {
+        for (int stage = 0; stage < 3; ++stage) {
+            App *a = script ? fresh_automatic("/away Script replacement", NULL, 1) : fresh(0);
+            SendPlan plan;
+            register_plain(a);
+            a->cfg.background_away = 1;
+            strcpy(a->cfg.background_away_message, "Detached");
+            assert(app_command(a, "/back", &plan) == 1);
+            app_network(a, 0);
+            output_clear(a);
+            if (stage == 1) a->net->block = 1;
+            if (stage == 2) a->net->write_limit = 3;
+            if (script) clock_ms += 1000;
+            else assert(app_command(a, "/away Manual replacement", &plan) == 1);
+            app_network(a, 0);
+            assert(a->manual_away_pending);
+            assert(stage ? a->inflight != NULL : a->inflight == NULL);
+            feed(a, ":server 305 tester :Earlier BACK confirmed\r\n");
+            assert(!a->away && a->manual_away_pending);
+            app_set_backgrounded(a, 1);
+            app_network(a, 0);
+            a->net->block = 0;
+            a->net->write_limit = 0;
+            app_network(a, 0);
+            const char *expected = script ? "AWAY :Script replacement\r\n" : "AWAY :Manual replacement\r\n";
+            assert(!strcmp(a->net->output, expected));
+            feed(a, ":server 306 tester :Later AWAY confirmed\r\n");
+            assert(a->away && !a->manual_away_pending && a->automatic_away == APP_AUTO_AWAY_NONE);
+            clock_ms += 1000;
+            app_network(a, 0);
+            assert(!strcmp(a->net->output, expected));
+            app_set_backgrounded(a, 0);
+            assert(app_command(a, "/back", &plan) == 1 && !a->manual_away_pending);
+            app_network(a, 0);
+            feed(a, ":server 305 tester :Latest BACK confirmed\r\n");
+            assert(!a->away && !a->manual_away_pending);
+            destroy(a);
+        }
+    }
+}
+
+static void disabled_policy_preserves_clear(void)
+{
+    App *a = failed_return(1, 1);
+    Config desired;
+    char error[512];
+    app_config_effective(a, &desired);
+    desired.background_away = 0;
+    desired.autoaway_minutes = 0;
+    assert(app_config_apply(a, &desired, 0, error, sizeof error));
+    drain_control_queue(a);
+    output_clear(a);
+    clock_ms += 1000;
+    app_network(a, 0);
+    assert(!strcmp(a->net->output, "AWAY\r\n"));
+    assert(a->automatic_away == APP_AUTO_AWAY_NONE && !a->automatic_away_retry_at);
+    destroy(a);
+}
+
+static void reconnect_discards_clear(void)
+{
+    App *a = failed_return(1, 1);
+    app_disconnect(a, "Reconnect fixture");
+    assert(!a->automatic_away_retry_at && a->automatic_away == APP_AUTO_AWAY_NONE);
+    assert(app_connect(a));
+    app_network(a, 0);
+    register_plain(a);
+    output_clear(a);
+    clock_ms += 5000;
+    app_network(a, 0);
+    assert(!a->net->output_len && !a->automatic_away_retry_at);
+    destroy(a);
+}
+
+int main(int argc, char **argv)
+{
+    static const struct { const char *name; void (*run)(void); } cases[] = {
+        {"bounded-retry", bounded_clear_retry}, {"manual-priority", newer_manual_presence},
+        {"renewed-background", renewed_background_presence}, {"server-confirmation", server_presence_confirmation},
+        {"script-priority", newer_script_presence}, {"cancel-restore", cancelled_script_restores_clear},
+        {"reject-restore", rejected_script_restores_clear}, {"disabled-policy", disabled_policy_preserves_clear},
+        {"background-after-script", background_after_script_cancel},
+        {"old-confirmation-during-script", old_confirmation_during_script},
+        {"manual-confirmation-during-script", manual_confirmation_during_script},
+        {"foreground-during-script", foreground_while_script_pending},
+        {"activity-preserves-manual", activity_preserves_prior_manual_away},
+        {"stale-back-confirmation", stale_back_confirmation_after_away},
+        {"reconnect", reconnect_discards_clear}
+    };
+    int matched = 0;
+    assert(argc == 1 || argc == 2);
+    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i)
+        if (argc == 1 || !strcmp(argv[1], cases[i].name)) {
+            cases[i].run();
+            printf("presence recovery: %s passed\n", cases[i].name);
+            matched = 1;
+        }
+    assert(matched);
+    return 0;
+}

