local/probe_config_commit.c.contents:
/* Storage-fault observation, not a real disk fault. Production configuration
 * writes use real private files; only one chosen fsync call returns EIO. */
#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif
#include <assert.h>
#include <errno.h>
#include <sys/stat.h>
#include <unistd.h>
static int fault_kind;
static int boundary_fsync(int fd)
{
    struct stat st;
    assert(!fstat(fd, &st));
    if ((fault_kind == 1 && S_ISREG(st.st_mode)) || (fault_kind == 2 && S_ISDIR(st.st_mode))) {
        fault_kind = 0; errno = EIO; return -1;
    }
    return fsync(fd);
}
#define fsync boundary_fsync
#include "config.c"
#undef fsync
#define main previous_client_suite
#include "test_client.c"
#undef main

int main(void)
{
    char directory[] = "/tmp/irc-config-commit-XXXXXX", primary[CONFIG_PATH_MAX], error[512];
    assert(mkdtemp(directory));
    assert(snprintf(primary, sizeof primary, "%s/config.ini", directory) > 0);
    Config old, changed, loaded;
    config_defaults(&old); strcpy(old.server, "before.invalid"); strcpy(old.nick, "Before");
    changed = old; strcpy(changed.server, "after.invalid"); strcpy(changed.nick, "After");
    assert(config_save(&old, primary, error, sizeof error) == 1);
    Client *client = calloc(1, sizeof *client); assert(client);
    assert(client_init(client, &old, primary, "fixture", 0, 1, error, sizeof error) == 1);
    for (int kind = 1; kind <= 2; ++kind) {
        fault_kind = kind;
        int result = client_save(client, 0, &changed, error, sizeof error);
        assert(result == -1 && !fault_kind);
        printf("%s synchronization fault: return=%d; diagnostic=%s\n", kind == 1 ? "file" : "directory", result, error);
        config_defaults(&loaded);
        assert(config_load(&loaded, primary, error, sizeof error) == 1);
        assert(!strcmp(loaded.server, kind == 1 ? "before.invalid" : "after.invalid"));
        assert(!strcmp(client->slots[0].seed.server, "before.invalid"));
        printf("  disk endpoint=%s; runtime seed=%s\n", loaded.server, client->slots[0].seed.server);
    }
    assert(client_save(client, 0, &changed, error, sizeof error) == 1);
    assert(!strcmp(client->slots[0].seed.server, "after.invalid"));
    puts("retry succeeds; runtime and saved state agree; no configuration secret or network connection used");
    client_free(client); free(client); remove_tree(directory);
    return 0;
}

local/probe_helper_descendant.c.contents:
/* Private helper lifecycle probe. Uses real fork/exec/pipes/signals.
 * The helper is this test executable, not GnuPG or a real keyring.
 * Linux subreaping is test-only so every created process can be collected. */
#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif
#include "credentials.c"
#include <assert.h>
#include <poll.h>
#include <sys/prctl.h>
#include <time.h>

static int64_t now_ms(void)
{
    struct timespec now;
    assert(!clock_gettime(CLOCK_MONOTONIC, &now));
    return (int64_t)now.tv_sec * 1000 + now.tv_nsec / 1000000;
}

static void put_bytes(int fd, const char *data)
{
    size_t length = strlen(data), offset = 0;
    while (offset < length) {
        ssize_t n = write(fd, data + offset, length - offset);
        if (n < 0 && errno == EINTR) continue;
        assert(n > 0); offset += (size_t)n;
    }
}

static int helper(int encrypt)
{
    char request[128];
    ssize_t count = read(0, request, sizeof request);
    assert(count > 0);
    pid_t child = fork(); assert(child >= 0);
    if (!child) {
        int fd = open(getenv("IRC_TEST_DESCENDANT_PATH"), O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC, 0600);
        assert(fd >= 0);
        char identity[80];
        assert(snprintf(identity, sizeof identity, "%ld %ld\n", (long)getpid(), (long)getpgrp()) > 0);
        put_bytes(fd, identity); assert(!close(fd));
        /* Keep only the inherited stdout/status writers. The direct helper
         * exits successfully while this descendant keeps both pipes open. */
        close(0); close(2);
        for (;;) pause();
    }
    put_bytes(1, encrypt ? "ENCRYPTED-FIXTURE" : "fixture-secret");
    put_bytes(3, encrypt ? "[GNUPG:] BEGIN_ENCRYPTION 2 9\n[GNUPG:] END_ENCRYPTION\n" :
                          "[GNUPG:] DECRYPTION_INFO 2 9\n[GNUPG:] DECRYPTION_OKAY\n[GNUPG:] END_DECRYPTION\n");
    return 0;
}

int main(int argc, char **argv)
{
    if (!strcmp(argv[0], "gpg")) return helper(argc > 1 && !strcmp(argv[argc - 1], "--encrypt"));
    assert(!prctl(PR_SET_CHILD_SUBREAPER, 1, 0, 0, 0));
    char directory[] = "/tmp/irc-helper-descendant-XXXXXX", executable[4096];
    char program[4096], source[4096], destination[4096], report[4096];
    char error[512], out[CONFIG_SECRET_MAX + 1];
    assert(realpath(argv[0], executable) && mkdtemp(directory));
    assert(snprintf(program, sizeof program, "%s/gpg", directory) > 0);
    assert(snprintf(source, sizeof source, "%s/input.gpg", directory) > 0);
    assert(snprintf(destination, sizeof destination, "%s/output.gpg", directory) > 0);
    assert(snprintf(report, sizeof report, "%s/descendant.pid", directory) > 0);
    assert(!symlink(executable, program));
    assert(!setenv("PATH", directory, 1));
    assert(!setenv("IRC_TEST_DESCENDANT_PATH", report, 1));
    int input = open(source, O_WRONLY | O_CREAT | O_EXCL, 0600); assert(input >= 0);
    put_bytes(input, "orphan-fixture"); assert(!close(input));
    for (int encrypt = 0; encrypt < 2; ++encrypt) {
        int64_t began = now_ms();
        Credential *read_job = NULL;
        CredentialCreate *write_job = NULL;
        if (encrypt)
            write_job = credential_create_start(destination, "0123456789abcdef0123456789abcdef01234567", "fixture-secret", began, error, sizeof error);
        else read_job = credential_start(source, began, error, sizeof error);
        assert(read_job || write_job);
        size_t slot = encrypt ? write_job->child : read_job->child;
        pid_t leader = children[slot].pid;
        int exited = 0, result = 0;
        while (now_ms() - began < 2000) {
            result = encrypt ? credential_create_poll(write_job, now_ms(), error, sizeof error) :
                               credential_poll(read_job, now_ms(), out, sizeof out, error, sizeof error);
            assert(result == 0);
            exited = encrypt ? write_job->exited : read_job->exited;
            if (exited && !access(report, F_OK)) break;
            (void)poll(NULL, 0, 2);
        }
        assert(exited && !children[slot].pid);
        FILE *file = fopen(report, "r"); assert(file);
        long descendant, group; assert(fscanf(file, "%ld %ld", &descendant, &group) == 2);
        assert(!fclose(file) && group == (long)leader);
        result = encrypt ? credential_create_poll(write_job, began + CREDENTIAL_TIMEOUT_MS, error, sizeof error) :
                           credential_poll(read_job, began + CREDENTIAL_TIMEOUT_MS, out, sizeof out, error, sizeof error);
        assert(result == -1 && strstr(error, "timed out"));
        if (encrypt) credential_create_cancel(write_job); else credential_cancel(read_job);
        int alive = kill((pid_t)descendant, 0) == 0;
        printf("%s: leader reaped before pipe EOF; timeout=-1; descendant alive after cancellation=%d; cleanup_pending=%d\n",
               encrypt ? "encrypt" : "decrypt", alive, credential_cleanup_pending());
        /* Explicit fixture cleanup is independent of the behavior under test. */
        if (alive) { assert(!kill(-leader, SIGKILL)); assert(!kill((pid_t)descendant, SIGKILL)); }
        int status; assert(waitpid((pid_t)descendant, &status, 0) == (pid_t)descendant);
        assert(!unlink(report));
    }
    assert(!unlink(source) && !unlink(program) && !rmdir(directory));
    return 0;
}

local/run_local_checks.py.contents:
#!/usr/bin/env python3
import concurrent.futures,hashlib,json,os,pathlib,subprocess,time
base=pathlib.Path(__file__).resolve().parents[2]
out=base/'irc-deep-validation'/'local'
cases=[]
for app,version in [('onekeyirc','0.1.27'),('vipirc','0.7.28')]:
    project=base/'irc-deep-work'/f'{app}-{version}'
    for name in ['credential_descendants','credential_signals','background_rights','credentials','credential_lifecycle']:
        for sanitize in ([False,True] if name in ['credential_descendants','credential_signals','background_rights'] else [False]):
            cases.append((app,project,name,sanitize))
def run(case):
    app,project,name,sanitize=case
    label=f'{app}-{name}'+('-sanitize' if sanitize else '')
    binary=out/label
    sources=[project/'tests'/f'test_{name}.c']
    if name!='background_rights':
        if name=='credentials':sources.append(project/'src'/'credentials.c')
        sources.extend(project/'src'/f'{s}.c' for s in ['config','autocommands','protocol'])
    command=['cc','-std=c11','-O1','-g','-Wall','-Wextra','-Werror','-D_DEFAULT_SOURCE','-D_XOPEN_SOURCE=700']
    if app=='onekeyirc':command.append('-DONEKEY_ONLY')
    if sanitize:command.extend(['-fsanitize=address,undefined','-fno-omit-frame-pointer'])
    command.extend(['-I'+str(project/'src'),'-I'+str(project/'tests'),'-o',str(binary)])
    command.extend(map(str,sources))
    environment=dict(os.environ)
    if sanitize:environment.update(ASAN_OPTIONS='detect_leaks=0:abort_on_error=1',UBSAN_OPTIONS='halt_on_error=1')
    began=time.monotonic()
    built=subprocess.run(command,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
    result={'name':label,'compile':command,'compile_exit':built.returncode,'run_exit':None,'log':str(out/(label+'.txt'))}
    text=built.stdout
    if not built.returncode:
        ran=subprocess.run([str(binary)],env=environment,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=45)
        result['run_exit']=ran.returncode;text+=ran.stdout
    result['seconds']=round(time.monotonic()-began,3)
    if sanitize:result['sanitizers']={'address':True,'undefined':True,'leaks':False,'reason':'Existing environment limitation; this run does not claim LeakSanitizer coverage.'}
    pathlib.Path(result['log']).write_text(text)
    return result
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
    results=list(executor.map(run,cases))
(out/'local-checks.json').write_text(json.dumps(results,indent=2)+'\n')
for result in results:print(result['name']+': compile='+str(result['compile_exit'])+' run='+str(result['run_exit']))
raise SystemExit(any(r['compile_exit'] or r['run_exit'] for r in results))

