         failure(error, cap, "The credential must be one line without control bytes."); return NULL;
     }
+    if (child_ownership_safe(error, cap) < 0) return NULL;
     credential_reap();
     size_t slot;
     for (slot = 0; slot < CREDENTIAL_JOBS && children[slot].pid; ++slot) { }
@@ -807,7 +828,9 @@
