#define _POSIX_C_SOURCE 200809L
#include "net.h"
#include <arpa/inet.h>
#include <assert.h>
#include <errno.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>
#include <openssl/err.h>
#include <openssl/ssl.h>

static unsigned incoming_updates;
static void message(int sending, int version, int content, const void *data,
                    size_t size, SSL *ssl, void *arg)
{
    (void)version; (void)ssl; (void)arg;
    if (!sending && content == SSL3_RT_HANDSHAKE && size &&
        ((const unsigned char *)data)[0] == SSL3_MT_KEY_UPDATE) ++incoming_updates;
}
SSL *budget_test_SSL_new(SSL_CTX *ctx)
{
    SSL *ssl = SSL_new(ctx);
    if (ssl) SSL_set_msg_callback(ssl, message);
    return ssl;
}
static void must(int condition, const char *label)
{
    if (!condition) { perror(label); ERR_print_errors_fp(stderr); exit(2); }
}
static void pipe_write(int fd, const void *data, size_t size)
{
    must(write(fd, data, size) == (ssize_t)size, "pipe write");
}
static void pipe_read(int fd, void *data, size_t size)
{
    must(read(fd, data, size) == (ssize_t)size, "pipe read");
}
static void serve(int listener, int control, int status, const char *cert,
                  const char *key, unsigned count)
{
    SSL_CTX *ctx = SSL_CTX_new(TLS_server_method());
    SSL *ssl;
    char marker;
    int sock = accept(listener, NULL, NULL), large = 4 * 1024 * 1024;
    alarm(20);
    must(sock >= 0, "accept"); close(listener);
    must(setsockopt(sock, SOL_SOCKET, SO_SNDBUF, &large, sizeof large) == 0, "sndbuf");
    must(ctx != NULL, "SSL_CTX_new");
    must(SSL_CTX_set_min_proto_version(ctx, TLS1_3_VERSION) == 1, "TLS minimum");
    must(SSL_CTX_set_max_proto_version(ctx, TLS1_3_VERSION) == 1, "TLS maximum");
    must(SSL_CTX_use_certificate_file(ctx, cert, SSL_FILETYPE_PEM) == 1, "certificate");
    must(SSL_CTX_use_PrivateKey_file(ctx, key, SSL_FILETYPE_PEM) == 1, "key");
    must(SSL_CTX_set_num_tickets(ctx, 0) == 1, "tickets");
    ssl = SSL_new(ctx); must(ssl != NULL, "server SSL");
    must(SSL_set_fd(ssl, sock) == 1, "server fd");
    must(SSL_accept(ssl) == 1, "server handshake");
    pipe_read(control, &marker, 1);
    for (unsigned i = 0; i < count; ++i) {
        must(SSL_key_update(ssl, SSL_KEY_UPDATE_NOT_REQUESTED) == 1, "key update");
        must(SSL_do_handshake(ssl) == 1, "key update send");
    }
    must(SSL_write(ssl, "PING :control-budget\r\n", 22) == 22, "marker data");
    marker = 'K'; pipe_write(status, &marker, 1);
    pipe_read(control, &marker, 1);
    SSL_free(ssl); SSL_CTX_free(ctx); close(sock); close(control); close(status);
    _exit(0);
}
int main(int argc, char **argv)
{
    int listener, control[2], status[2], child_status;
    struct sockaddr_in addr;
    socklen_t addr_size = sizeof addr;
    pid_t child;
    char error[512], bytes[1024], marker = 'R';
    Net *net;
    int64_t deadline, before, after;
    unsigned count;
    must(argc == 4, "arguments"); count = (unsigned)strtoul(argv[3], NULL, 10);
    signal(SIGPIPE, SIG_IGN); alarm(25);
    listener = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP); must(listener >= 0, "listener");
    memset(&addr, 0, sizeof addr); addr.sin_family = AF_INET; addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    must(bind(listener, (struct sockaddr *)&addr, sizeof addr) == 0, "bind");
    must(getsockname(listener, (struct sockaddr *)&addr, &addr_size) == 0, "getsockname");
    must(listen(listener, 1) == 0, "listen");
    must(pipe(control) == 0 && pipe(status) == 0, "pipes");
    child = fork(); must(child >= 0, "fork");
    if (!child) { close(control[1]); close(status[0]); serve(listener, control[0], status[1], argv[1], argv[2], count); }
    close(listener); close(control[0]); close(status[1]);
    net = net_open("127.0.0.1", ntohs(addr.sin_port), 1, argv[1], error, sizeof error);
    must(net != NULL, error);
    deadline = net_now_ms() + 8000;
    while (net_state(net) != NET_READY && net_state(net) != NET_FAILED && net_now_ms() < deadline) {
        struct pollfd p = {net_fd(net), net_events(net, 0), 0};
        must(poll(&p, 1, 50) >= 0, "setup poll");
        (void)net_step(net, p.revents, net_now_ms());
    }
    must(net_state(net) == NET_READY, net_error(net));
    pipe_write(control[1], &marker, 1);
    pipe_read(status[0], &marker, 1); must(marker == 'K', "server sent marker");
    before = net_now_ms();
    ssize_t got = net_read(net, bytes, sizeof bytes);
    after = net_now_ms();
    printf("first_read=%zd processed_key_updates=%u offered=%u elapsed_ms=%lld state=%d pending=%d error=%s\n",
           got, incoming_updates, count, (long long)(after - before), (int)net_state(net), net_pending(net), net_error(net));
    fflush(stdout);
    pipe_write(control[1], &marker, 1);
    net_close(net); close(control[1]); close(status[0]);
    must(waitpid(child, &child_status, 0) == child, "wait child");
    must(WIFEXITED(child_status) && WEXITSTATUS(child_status) == 0, "child status");
    return incoming_updates > 1 ? 1 : 0;
}

network/probe_tls_interleave.c.contents:
#define _POSIX_C_SOURCE 200809L
#include "net.h"
#include <arpa/inet.h>
#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>
#include <openssl/err.h>
#include <openssl/ssl.h>

static void must(int condition, const char *label)
{
    if (!condition) { perror(label); ERR_print_errors_fp(stderr); exit(2); }
}

static void pipe_write(int fd, const void *data, size_t size)
{
    const unsigned char *p = data;
    while (size) {
        ssize_t n = write(fd, p, size);
        if (n < 0 && errno == EINTR) continue;
        must(n > 0, "pipe write"); p += n; size -= (size_t)n;
    }
}

static void pipe_read(int fd, void *data, size_t size)
{
    unsigned char *p = data;
    while (size) {
        ssize_t n = read(fd, p, size);
        if (n < 0 && errno == EINTR) continue;
        must(n > 0, "pipe read"); p += n; size -= (size_t)n;
    }
}

static void server(int listener, int control, int status, const char *cert, const char *key)
{
    SSL_CTX *ctx = SSL_CTX_new(TLS_server_method());
    SSL *ssl;
    unsigned char bytes[65536], marker;
    uint64_t expected, received = 0;
    int sock = accept(listener, NULL, NULL), small = 4096;
    alarm(12);
    must(sock >= 0, "accept"); close(listener);
    must(setsockopt(sock, SOL_SOCKET, SO_RCVBUF, &small, sizeof small) == 0, "server rcvbuf");
    must(ctx != NULL, "SSL_CTX_new");
    must(SSL_CTX_set_min_proto_version(ctx, TLS1_3_VERSION) == 1, "TLS minimum");
    must(SSL_CTX_set_max_proto_version(ctx, TLS1_3_VERSION) == 1, "TLS maximum");
    must(SSL_CTX_use_certificate_file(ctx, cert, SSL_FILETYPE_PEM) == 1, "certificate");
    must(SSL_CTX_use_PrivateKey_file(ctx, key, SSL_FILETYPE_PEM) == 1, "key");
    must(SSL_CTX_set_num_tickets(ctx, 0) == 1, "tickets");
    ssl = SSL_new(ctx); must(ssl != NULL, "server SSL");
    must(SSL_set_fd(ssl, sock) == 1, "server fd");
    must(SSL_accept(ssl) == 1, "server handshake");
    marker = 'R'; pipe_write(status, &marker, 1);
    pipe_read(control, &expected, sizeof expected);
    must(SSL_key_update(ssl, SSL_KEY_UPDATE_REQUESTED) == 1, "key update");
    must(SSL_do_handshake(ssl) == 1, "key update send");
    marker = 'K'; pipe_write(status, &marker, 1);
    pipe_read(control, &marker, 1);
    while (received < expected) {
        int n = SSL_read(ssl, bytes, sizeof bytes);
        must(n > 0, "server read");
        for (int i = 0; i < n; ++i) must(bytes[i] == (unsigned char)((received + (uint64_t)i) % 251u), "stream bytes");
        received += (uint64_t)n;
    }
    must(received == expected, "stream length");
    must(SSL_write(ssl, "OK", 2) == 2, "server ack");
    SSL_shutdown(ssl);
    SSL_free(ssl); SSL_CTX_free(ctx); close(sock);
    close(control); close(status);
    _exit(0);
}

int main(int argc, char **argv)
{
    int listener, control[2], status[2], small = 4096, child_status;
    struct sockaddr_in addr;
    socklen_t addr_size = sizeof addr;
    pid_t child;
    unsigned char bytes[65536], reply[1024], marker;
    char error[512];
    Net *net;
    size_t sent = 0, pending_size = 0, received = 0;
    ssize_t n;
    int64_t deadline;
    must(argc == 3, "arguments");
    signal(SIGPIPE, SIG_IGN); alarm(15);
    listener = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP); must(listener >= 0, "listener");
    memset(&addr, 0, sizeof addr); addr.sin_family = AF_INET; addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    must(bind(listener, (struct sockaddr *)&addr, sizeof addr) == 0, "bind");
    must(getsockname(listener, (struct sockaddr *)&addr, &addr_size) == 0, "getsockname");
    must(listen(listener, 1) == 0, "listen");
    must(pipe(control) == 0 && pipe(status) == 0, "pipes");
    child = fork(); must(child >= 0, "fork");
    if (!child) { close(control[1]); close(status[0]); server(listener, control[0], status[1], argv[1], argv[2]); }
    close(listener); close(control[0]); close(status[1]);
    net = net_open("127.0.0.1", ntohs(addr.sin_port), 1, argv[1], error, sizeof error);
    must(net != NULL, error);
    deadline = net_now_ms() + 8000;
    while (net_state(net) != NET_READY && net_state(net) != NET_FAILED && net_now_ms() < deadline) {
        struct pollfd p = {net_fd(net), net_events(net, 0), 0};
        must(poll(&p, 1, 50) >= 0, "setup poll");
        (void)net_step(net, p.revents, net_now_ms());
    }
    must(net_state(net) == NET_READY, net_error(net));
    pipe_read(status[0], &marker, 1); must(marker == 'R', "ready marker");
    must(setsockopt(net_fd(net), SOL_SOCKET, SO_SNDBUF, &small, sizeof small) == 0, "client sndbuf");
    for (size_t attempt = 0; attempt < 1024; ++attempt) {
        for (size_t i = 0; i < sizeof bytes; ++i) bytes[i] = (unsigned char)((sent + i) % 251u);
        n = net_write(net, bytes, sizeof bytes);
        if (n == -2) { pending_size = sizeof bytes; break; }
        must(n > 0, net_error(net)); sent += (size_t)n;
    }
    must(pending_size != 0, "write stalled");
    printf("stalled after %zu bytes; events=%d\n", sent, (int)net_events(net, 1)); fflush(stdout);
    uint64_t expected = sent + pending_size;
    pipe_write(control[1], &expected, sizeof expected);
    pipe_read(status[0], &marker, 1); must(marker == 'K', "key-update marker");
    struct pollfd p = {net_fd(net), POLLIN, 0};
    must(poll(&p, 1, 1000) > 0 && (p.revents & POLLIN), "key-update readable");
    n = net_read(net, reply, sizeof reply);
    printf("read during stalled write=%zd state=%d events=%d error=%s\n", n, (int)net_state(net), (int)net_events(net, 1), net_error(net)); fflush(stdout);
    marker = 'D'; pipe_write(control[1], &marker, 1);
    must(n == -2 && net_state(net) == NET_READY, "key-update read should wait");
    size_t pending_done = 0;
    while (pending_done < pending_size && net_now_ms() < deadline) {
        p.fd = net_fd(net); p.events = net_events(net, 1); p.revents = 0;
        must(poll(&p, 1, 50) >= 0, "write poll");
        n = net_write(net, bytes + pending_done, pending_size - pending_done);
        if (n == -2) continue;
        printf("write retry result=%zd state=%d error=%s\n", n, (int)net_state(net), net_error(net)); fflush(stdout);
        must(n > 0, net_error(net)); sent += (size_t)n; pending_done += (size_t)n;
    }
    must(sent == expected, "write retry completed");
    while (received < 2 && net_now_ms() < deadline) {
        p.fd = net_fd(net); p.events = net_events(net, 0); p.revents = 0;
        must(poll(&p, 1, net_pending(net) ? 0 : 50) >= 0, "read poll");
        n = net_read(net, reply + received, sizeof reply - received);
        if (n == -2) continue;
        must(n > 0, net_error(net)); received += (size_t)n;
    }
    must(received == 2 && !memcmp(reply, "OK", 2), "ack");
    net_close(net); close(control[1]); close(status[0]);
    must(waitpid(child, &child_status, 0) == child, "wait child");
    must(WIFEXITED(child_status) && WEXITSTATUS(child_status) == 0, "child status");
    printf("PASS: real TLS KeyUpdate interleaved with stalled write; sent=%zu\n", sent);
    return 0;
}

