/* Ordinary return-to-foreground with a temporarily full control queue. */
#define main legacy_app_test_main
#include "test_app.c"
#undef main

int main(void)
{
    App *a = fresh(0);
    register_plain(a);
    a->cfg.background_away = 1;
    strcpy(a->cfg.background_away_message, "Detached");
    app_set_backgrounded(a, 1);
    app_network(a, 0);
    feed(a, ":server 306 tester :Away\r\n");
    assert(a->away && a->automatic_away == APP_AUTO_AWAY_BACKGROUND);
    output_clear(a);
    for (size_t i = 0; i < APP_QUEUE; ++i)
        assert(app_outgoing(a, 0, "PING :queued-control-%zu", i));
    app_set_backgrounded(a, 0);
    assert(a->control_count == APP_QUEUE && a->automatic_away == APP_AUTO_AWAY_BACKGROUND);
    for (size_t i = 0; i < 5; ++i) {
        clock_ms += 1000;
        app_network(a, 0);
    }
    assert(!a->control_count && !a->inflight);
    if (!strstr(a->net->output, "AWAY\r\n")) {
        puts("OBSERVED: return-to-foreground AWAY clear was not retried after the control queue drained");
        fflush(stdout);
    }
    assert(strstr(a->net->output, "AWAY\r\n"));
    assert(a->automatic_away == APP_AUTO_AWAY_NONE);
    destroy(a);
    return 0;
}

